    L,C=max(Mc,G),min(Mc,G)
    horiz = len(g[0])>=len(g)  # guess orientation by bar shape instead
    # determine orientation: bars lie along an edge row or edge column
    # horizontal bars: contiguous B runs in first/last row; vertical: in first/last col
    trow=[i for i,x in enumerate(g[0]) if x==B]; brow=[i for i,x in enumerate(g[-1]) if x==B]
    tcol=[i for i,x in enumerate(g[:,0]) if x==B] if False else [i for i in range(h) if g[i][0]==B]
    bcol=[i for i in range(h) if g[i][w-1]==B]
    if trow and brow:
        horiz=True; tspan=(trow[0],trow[-1]); bspan=(brow[0],brow[-1])
        def ray(a,b): return range(a,b+1)
    else:
        horiz=False; tspan=(tcol[0],tcol[-1]); bspan=(bcol[0],bcol[-1])  # left bar, right bar
    marks=[(r,c) for r in range(h) for c in range(w) if g[r][c]==Mc]
    out=[[G]*w for _ in range(h)]
    if horiz:
        # beams: top bar casts down over its col span rows0..h-1; bottom bar casts up over its span
        for c in range(tspan[0],tspan[1]+1):
            for r in range(h): out[r][c]=C
        for c in range(bspan[0],bspan[1]+1):
            for r in range(h): out[r][c]=C
        mcols={c for r,c in marks}
