        # far (top) bar stripes at marker offsets: full beam extent shifted one down
        if mcols <= set(range(tspan[0],tspan[1]+1)) or True:
            pass
        markers_in_bottom = mcols <= set(range(bspan[0],bspan[1]+1))
        if markers_in_bottom:
            for o in off:
                c=tspan[0]+o
                if tspan[0]<=c<=tspan[1]:
                    for r in range(1,h): out[r][c]=L
        # marker lines: down from marker to before bottom bar row (h-1)
        for r,c in marks:
            out[r][c]=4
            for rr in range(r+1,h-1): out[rr][c]=L
        # gap lines (G): each bar's beam extent minus own row, at uncovered offsets
        for span,is_top in ((tspan,True),(bspan,False)):
            sw=span[1]-span[0]+1
            for o in range(sw):
                if o not in off:
                    c=span[0]+o
                    rng = range(1,h-1) if is_top else range(0,h-1)
                    for r in rng: out[r][c]=G
    else:
        # vertical bars: left bar casts right-beam, right bar casts left-beam, over their row spans
        for r in range(tspan[0],tspan[1]+1):
            for c in range(w): out[r][c]=C
        for r in range(bspan[0],bspan[1]+1):
            for c in range(w): out[r][c]=C
        mrows={r for r,c in marks}
        off={r-bspan[0] for r in mrows}  # from top end of markers' (right) bar span
        markers_in_right = mrows <= set(range(bspan[0],bspan[1]+1))
        if markers_in_right:
            for o in off:
                r=tspan[0]+o
                if tspan[0]<=r<=tspan[1]:
                    for c in range(1,w): out[r][c]=L
        for r,c in marks:
