            for cc in range(c+1,w-1): out[r][cc]=L
        for span,is_left in ((tspan,True),(bspan,False)):
            sw=span[1]-span[0]+1
            for o in range(sw):
                if o not in off:
                    r=span[0]+o
                    rng = range(1,w-1) if is_left else range(0,w-1)
                    for c in rng: out[r][c]=G
    # bars overwrite
    if horiz:
        for c in range(tspan[0],tspan[1]+1): out[0][c]=B
        for c in range(bspan[0],bspan[1]+1): out[h-1][c]=B
    else:
        for r in range(tspan[0],tspan[1]+1): out[r][0]=B
        for r in range(bspan[0],bspan[1]+1): out[r][w-1]=B
    return out

